class Solution {
public:
    int minMaxDifference(int num) {
        string s = to_string(num);

        // Maximum: find first non-9 digit, replace all occurrences with 9
        string maxS = s;
        char target = '9';
        for (char c : s) {
            if (c != '9') {
                target = c;
                break;
            }
        }
        for (char& c : maxS) {
            if (c == target) c = '9';
        }

        // Minimum: replace all occurrences of first digit with 0
        string minS = s;
        char minTarget = s[0];
        for (char& c : minS) {
            if (c == minTarget) c = '0';
        }

        return stoi(maxS) - stoi(minS);
    }
};
